"""Regression test: vectorized ``_build_link_cost`` must reproduce the exact
Hungarian-assignment behaviour of the nested-loop implementation it replaced.

Background: ``_build_link_cost`` used to fill its P x Q matrix with a plain
Python double loop calling ``_filament_cost`` per pair (2 cKDTree.query calls
each). At real production filament counts (mean 61.2/frame, p95 134, max
311 -- measured across 2423 production microtubule frames) that is up to
~193 000 cKDTree.query calls per frame-to-frame link, and profiling put 95
percent of /track's wall-clock inside this one function. The tree per
filament was already cached (see ``_Filament.tree``); the loop itself was
the remaining cost. The fix batches the curve-distance cKDTree queries per
row/column instead of per pair, and vectorizes the endpoint/orientation/
length terms with numpy broadcasting -- see the docstring on the production
function for the technique.

This file is the equivalence oracle for that rewrite. It reimplements the
PRE-optimization nested loop here (calling the unchanged, still-used-by-gap-
closing ``_filament_cost`` directly) and asserts, on both real production
polylines and synthetic data spanning the observed size range, that:

1. The two cost matrices agree (bit-for-bit on real data; to a tight
   ``np.allclose`` everywhere -- see ``test_synthetic_ulp_diff_does_not_flip_
   assignment`` for why a handful of synthetic cells differ by up to 1 ULP).
2. ``_solve_link_lap`` -- i.e. the actual ``linear_sum_assignment`` outcome
   that decides cross-frame ``trackId`` -- is IDENTICAL between the two
   matrices at every tested ``cost_threshold``. This is what actually
   matters: a changed cost matrix silently corrupting ``trackId`` is exactly
   the class of regression this project has shipped before.

Mutation-tested: perturbing any one of the four cost terms in the
production ``_build_link_cost`` (e.g. halving the curve-distance saturation
scale, or swapping ``w_end``/``w_len``) turns every real-data test in this
file red -- see the session notes for the exact mutation and result.
"""
from __future__ import annotations

import json
import sys
import time
from pathlib import Path

import numpy as np
import pytest

SEG_ROOT = Path(__file__).resolve().parents[1]
if str(SEG_ROOT) not in sys.path:
    sys.path.insert(0, str(SEG_ROOT))

from api.tracker_kymograph import (  # noqa: E402
    PolylineInput,
    _build_link_cost,
    _filament_cost,
    _filament_features,
    _solve_link_lap,
)

_DEFAULT_WEIGHTS = (0.5, 0.3, 0.1, 0.1)
_THRESHOLDS = (0.1, 0.3, 0.6, 0.9, 1.2, 2.0)


def _naive_build_link_cost(prev_feats, nxt_feats, img_diag, weights):
    """The exact code ``_build_link_cost`` used to run, kept here ONLY as the
    equivalence oracle -- production now uses the vectorized version."""
    P, Q = len(prev_feats), len(nxt_feats)
    if P == 0 or Q == 0:
        return np.zeros((P, Q), dtype=np.float64)
    w_curve, w_end, w_orient, w_len = weights
    base = np.empty((P, Q), dtype=np.float64)
    for i in range(P):
        for j in range(Q):
            base[i, j] = _filament_cost(
                prev_feats[i], nxt_feats[j], img_diag, w_curve, w_end, w_orient, w_len
            )
    return base


def _make_filaments(specs):
    """specs: iterable of (id, points_rc) -> list[_Filament]."""
    return [
        _filament_features(PolylineInput(id=pid, points_rc=pts)) for pid, pts in specs
    ]


def _random_filaments(n, seed, spread=2048.0, degenerate_frac=0.0):
    """Synthetic filaments spread over a `spread` px square field, matching
    the shape of the manual benchmark in the optimization task (random
    position + orientation + length, jittered centerline)."""
    rng = np.random.default_rng(seed)
    specs = []
    for k in range(n):
        if degenerate_frac and rng.random() < degenerate_frac:
            n_pts = int(rng.integers(0, 2))  # 0 or 1 point: tree is None
            pts = rng.uniform(0, spread, size=(n_pts, 2)).tolist()
        else:
            length = float(rng.uniform(10, 200))
            n_pts = max(2, int(length / 3))
            r0, c0 = rng.uniform(0, spread, size=2)
            angle = rng.uniform(0, 2 * np.pi)
            t = np.linspace(0, length, n_pts)
            noise = rng.normal(0, 1.5, size=(n_pts, 2))
            pts = (
                np.stack([r0 + t * np.sin(angle), c0 + t * np.cos(angle)], axis=1)
                + noise
            ).tolist()
        specs.append((f"f{k}", pts))
    return _make_filaments(specs)


def _img_diag_for(*feat_lists):
    pts = [pt for feats in feat_lists for f in feats for pt in (f.end_a, f.end_b)]
    if not pts:
        return 1.0
    coords = np.asarray(pts)
    return max(float(np.linalg.norm(coords.max(axis=0) - coords.min(axis=0))), 1.0)


def _assert_equivalent(
    prev_feats, nxt_feats, img_diag, weights=_DEFAULT_WEIGHTS, thresholds=_THRESHOLDS
):
    """The core equivalence assertion: cost matrices agree closely, AND the
    LAP assignment they feed agrees EXACTLY at every threshold tested."""
    naive = _naive_build_link_cost(prev_feats, nxt_feats, img_diag, weights)
    fast = _build_link_cost(prev_feats, nxt_feats, img_diag, weights)
    assert naive.shape == fast.shape == (len(prev_feats), len(nxt_feats))

    assert np.array_equal(
        np.isinf(naive), np.isinf(fast)
    ), "degenerate-geometry (inf) gate differs between naive and vectorized"

    finite = np.isfinite(naive) & np.isfinite(fast)
    if finite.any():
        max_abs = float(np.max(np.abs(naive[finite] - fast[finite])))
        assert np.allclose(naive[finite], fast[finite], atol=1e-9, rtol=1e-9), (
            f"cost matrices diverge beyond floating-point noise: max_abs_diff={max_abs:.3e}"
        )

    for thr in thresholds:
        links_naive = _solve_link_lap(naive, thr)
        links_fast = _solve_link_lap(fast, thr)
        assert links_naive == links_fast, (
            f"linear_sum_assignment (via _solve_link_lap) differs at "
            f"cost_threshold={thr}: naive={links_naive} fast={links_fast}"
        )
    return naive, fast


# ---------------------------------------------------------------------------
# Synthetic coverage across the observed production size range (mean 61.2,
# p95 134, max 311 polylines/frame).
# ---------------------------------------------------------------------------


class TestSyntheticEquivalence:
    @pytest.mark.parametrize(
        "p,q,seed",
        [
            (0, 0, 1),
            (0, 5, 2),
            (5, 0, 3),
            (1, 1, 4),
            (2, 3, 5),
            (5, 7, 6),
            (50, 50, 7),
            (100, 100, 8),
            (200, 200, 9),
            (311, 311, 10),
            (300, 250, 11),
            (30, 300, 12),
        ],
    )
    def test_equivalence_random(self, p, q, seed):
        prev = _random_filaments(p, seed)
        nxt = _random_filaments(q, seed + 1000)
        img_diag = _img_diag_for(prev, nxt)
        _assert_equivalent(prev, nxt, img_diag)

    @pytest.mark.parametrize("seed", [21, 22, 23])
    def test_equivalence_with_degenerate_filaments(self, seed):
        """A mix of 0/1-point (tree=None) filaments among normal ones must
        gate to `inf` identically in both implementations."""
        prev = _random_filaments(60, seed, degenerate_frac=0.15)
        nxt = _random_filaments(60, seed + 1000, degenerate_frac=0.15)
        img_diag = _img_diag_for(prev, nxt)
        _assert_equivalent(prev, nxt, img_diag)

    def test_equivalence_all_degenerate(self):
        """Every filament is a single point -> every tree is None -> every
        cell must be `inf` in both implementations (not 0, which a naive
        centroid-style distance would produce)."""
        prev = _make_filaments([(f"p{i}", [[float(i), 0.0]]) for i in range(5)])
        nxt = _make_filaments([(f"n{j}", [[0.0, float(j)]]) for j in range(4)])
        naive, fast = _assert_equivalent(prev, nxt, 100.0)
        assert np.all(np.isinf(naive))
        assert np.all(np.isinf(fast))

    def test_equivalence_asymmetric_weights(self):
        """Non-default weights (e.g. from a caller emphasising curve
        distance) must not change the equivalence."""
        prev = _random_filaments(80, seed=31)
        nxt = _random_filaments(80, seed=1031)
        img_diag = _img_diag_for(prev, nxt)
        _assert_equivalent(prev, nxt, img_diag, weights=(0.8, 0.1, 0.05, 0.05))

    def test_synthetic_ulp_diff_does_not_flip_assignment(self):
        """On synthetic data a small number of cells can differ from the
        naive reference by up to 1 ULP (~2.22e-16): `_geom_terms` computes
        endpoint distance via bare `np.linalg.norm(v)` (a BLAS nrm2/dot code
        path), while the vectorized form must use `np.linalg.norm(arr,
        axis=-1)` (a plain sum-of-squares code path) -- numpy does not
        guarantee these agree bit-for-bit. `_assert_equivalent` already
        tolerates this via `np.allclose`; this test additionally pins that
        the LAP assignment -- the only thing that actually matters for
        `trackId` -- never flips because of it, across many trials.
        """
        for seed in range(40, 60):
            prev = _random_filaments(80, seed)
            nxt = _random_filaments(80, seed + 1000)
            img_diag = _img_diag_for(prev, nxt)
            naive, fast = _assert_equivalent(prev, nxt, img_diag)
            # Confirm this test is actually exercising the ULP-noise regime
            # it documents, not vacuously passing on accidentally-identical
            # matrices.
            finite = np.isfinite(naive) & np.isfinite(fast)
            if finite.any() and not np.array_equal(naive[finite], fast[finite]):
                return
        pytest.fail(
            "expected at least one seed to reproduce the documented ULP-level "
            "float divergence; none did -- the numpy norm code paths this "
            "test guards against may have changed"
        )


