def _load_real_frame(raw_json):
    polys = json.loads(raw_json)
    specs = [(p["id"], [[pt["y"], pt["x"]] for pt in p["points"]]) for p in polys]
    return _make_filaments(specs)


class TestRealProductionData:
    def test_frame11_to_frame12_is_bit_exact(self):
        prev = _load_real_frame(_FRAME_11_JSON)
        nxt = _load_real_frame(_FRAME_12_JSON)
        assert len(prev) == 283
        assert len(nxt) == 311
        img_diag = _img_diag_for(prev, nxt)
        naive, fast = _assert_equivalent(prev, nxt, img_diag)
        assert np.array_equal(naive, fast), (
            "expected bit-for-bit equality on real production filaments "
            "(observed on 2026-08-25); a difference here means the "
            "vectorization changed behaviour, not just floating-point "
            "reassociation noise"
        )

    def test_frame12_to_frame13_is_bit_exact(self):
        prev = _load_real_frame(_FRAME_12_JSON)
        nxt = _load_real_frame(_FRAME_13_JSON)
        assert len(prev) == 311
        assert len(nxt) == 303
        img_diag = _img_diag_for(prev, nxt)
        naive, fast = _assert_equivalent(prev, nxt, img_diag)
        assert np.array_equal(naive, fast)


# ---------------------------------------------------------------------------
# Performance smoke check -- not a benchmark (see the session's reported
# numbers for that), just a guard against silently regressing back toward
# O(P*Q) call-count behaviour.
# ---------------------------------------------------------------------------


class TestPerformance:
    def test_311x311_is_at_least_5x_faster_than_naive(self):
        prev = _random_filaments(311, seed=555)
        nxt = _random_filaments(311, seed=556)
        img_diag = _img_diag_for(prev, nxt)

        t0 = time.perf_counter()
        _naive_build_link_cost(prev, nxt, img_diag, _DEFAULT_WEIGHTS)
        t1 = time.perf_counter()
        _build_link_cost(prev, nxt, img_diag, _DEFAULT_WEIGHTS)
        t2 = time.perf_counter()

        naive_t, fast_t = t1 - t0, t2 - t1
        assert fast_t * 5 < naive_t, (
            f"expected >=5x speedup at P=Q=311, got naive={naive_t:.3f}s "
            f"fast={fast_t:.3f}s"
        )
